INSERT INTO kn_posts (lang, slug, title, excerpt, content, status, published_at, category_id, featured_image, meta_title, meta_description, og_image)
SELECT 'fr', 'comment-bien-nettoyer-son-canape-et-quand-faire-appel-a-un-pro', 'Comment bien nettoyer son canapé et quand faire appel à un professionnel ?', 'Tissu, cuir ou velours : les bons gestes pour nettoyer son canapé à la maison, les limites du nettoyage maison et les signes qui doivent vous faire appeler un professionnel.', '[{"type":"text","bg":"white","html":"<p><strong>Un canapé se salit plus vite qu\'on ne le croit : miettes, poussière, poils, transpiration, boissons renversées.</strong> Bien l\'entretenir prolonge sa vie et garde votre salon sain, quelle que soit la matière. Dans ce guide, nous voyons ce que vous pouvez faire vous-même selon que votre canapé est en tissu, en cuir ou en velours, où s\'arrêtent les gestes maison, et à quel moment il vaut mieux appeler un professionnel.</p><h2 class=\\"kn-subtitle\\">L\'essentiel en un coup d\'œil</h2><ul class=\\"kn-checklist\\"><li><strong>À la maison :</strong> aspirer régulièrement, traiter les taches vite, adapter les produits à la matière.</li><li><strong>Limite :</strong> le nettoyage maison reste en surface, la saleté profonde demande du matériel.</li><li><strong>Faire appel à un pro :</strong> taches tenaces, odeurs, allergies, ou plus de 6 mois sans nettoyage.</li><li><strong>Tarif professionnel :</strong> à partir de 110 €, déplacement compris, paiement après la prestation.</li></ul>","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"cream","eyebrow":"POURQUOI ENTRETENIR","h2":"Pourquoi un nettoyage régulier est important","intro":"Un canapé absorbe la poussière, les poils et les odeurs. Un entretien régulier améliore son aspect et la qualité de l\'air de la maison, en éliminant allergènes et germes.","columns":"1","items":[{"title":"Hygiène","desc":"Moins de bactéries et d\'allergènes dans les fibres, donc un salon plus sain."},{"title":"Durabilité","desc":"Un canapé propre s\'use moins vite et garde sa tenue plus longtemps."},{"title":"Aspect retrouvé","desc":"Les couleurs reprennent de l\'éclat et le toucher redevient agréable."}],"visible":["desktop","tablet","mobile"]},{"type":"text","bg":"white","html":"<h2 class=\\"kn-subtitle\\">Nettoyer son canapé à la maison : conseils selon la matière</h2><p>Chaque matière a ses besoins. Avant tout, <strong>lisez l\'étiquette d\'entretien</strong> et testez chaque produit sur une zone cachée du canapé.</p><h3>Canapé en tissu</h3><ul class=\\"kn-checklist\\"><li>Aspirez soigneusement pour retirer poussière et miettes, y compris entre les coussins.</li><li>Repérez le type de tissu grâce à l\'étiquette avant de choisir un produit.</li><li>Sur les tissus qui le permettent, utilisez de l\'eau tiède et un peu de liquide vaisselle.</li><li>Contre le gras, saupoudrez de bicarbonate ; contre le café ou le vin, tamponnez avec un mélange d\'eau et de vinaigre.</li><li>Rincez à peine et laissez sécher sans détremper le tissu.</li></ul><h3>Canapé en cuir</h3><ul class=\\"kn-checklist\\"><li>Dépoussiérez régulièrement avec un chiffon doux.</li><li>Nettoyez avec un produit spécial cuir ou de l\'eau légèrement savonneuse, puis essuyez.</li><li>Hydratez le cuir après chaque nettoyage pour éviter qu\'il sèche et craquelle.</li><li>Sur une tache grasse, tamponnez avec du talc, laissez absorber, puis brossez délicatement.</li></ul><h3>Canapé en velours</h3><ul class=\\"kn-checklist\\"><li>Aspirez doucement avec une brosse souple pour ménager les fibres.</li><li>Tamponnez les taches avec une éponge à peine humide et un savon doux.</li><li>Brossez dans le sens du poil pour redonner de la texture.</li><li>Pour une tache délicate, tamponnez avec du vinaigre blanc dilué.</li></ul><p>Dans tous les cas : tamponnez, ne frottez pas, et évitez de détremper la matière.</p>","visible":["desktop","tablet","mobile"]},{"type":"domicile-vs-atelier","bg":"white","eyebrow":"LES LIMITES","h2":"Les limites du nettoyage domestique","home_title":"Ce que vous pouvez faire seul","home_icon":"home","home_desc":"Pour l\'entretien courant, les gestes maison suffisent.","home_items":[{"icon":"check","label":"Aspirer chaque semaine"},{"icon":"check","label":"Traiter une tache fraîche"},{"icon":"check","label":"Dépoussiérer et aérer les coussins"},{"icon":"check","label":"Hydrater régulièrement un canapé en cuir"}],"workshop_title":"Ce qui demande un professionnel","workshop_icon":"shield","workshop_desc":"Certaines situations dépassent ce que l\'on peut obtenir à la maison :","workshop_items":[{"icon":"x","label":"Une saleté logée dans le rembourrage, hors d\'atteinte"},{"icon":"x","label":"Des produits inadaptés qui ternissent le cuir, décolorent le tissu ou abîment le velours"},{"icon":"x","label":"Des taches anciennes ou profondes qui résistent"}],"workshop_note":"Le nettoyage maison agit surtout en surface : germes et allergènes peuvent rester dans le rembourrage.","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"cream","eyebrow":"LE NETTOYAGE PROFESSIONNEL","h2":"Les avantages du nettoyage professionnel","intro":"Un professionnel apporte qualité et sécurité pour toutes les matières.","columns":"2","items":[{"title":"Un nettoyage en profondeur","desc":"Machines à vapeur et aspiration par injection-extraction éliminent taches, allergènes et bactéries jusque dans les couches profondes."},{"title":"Produits et méthodes adaptés","desc":"Des produits souvent hypoallergéniques et écologiques, adaptés aux foyers avec enfants ou animaux."},{"title":"Un aspect restauré","desc":"Texture du velours, éclat du cuir et couleur du tissu retrouvés : le canapé vieillit mieux."},{"title":"Du temps gagné","desc":"Le travail est fait sans effort de votre part."},{"title":"Moins de risques","desc":"Un expert évite les erreurs courantes : auréoles sur le cuir, plis sur le similicuir."}],"visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"rose","h2":"Quand faire appel à un professionnel du nettoyage de canapé ?","body":"<p>Faites-vous aider si vous remarquez :</p><ul class=\\"kn-checklist\\"><li>des <strong>taches profondes</strong> qui résistent au nettoyage maison ;</li><li>des <strong>odeurs persistantes</strong> (tabac, animaux) ;</li><li>des <strong>allergies fréquentes</strong>, souvent liées aux acariens ;</li><li><strong>plus de six mois</strong> sans nettoyage en profondeur.</li></ul>","cta_label":"Prenez RDV en ligne","cta_style":"primary","cta_align":"left","visible":["desktop","tablet","mobile"]},{"type":"pricing","bg":"white","eyebrow":"TARIFS","h2":"Le prix du nettoyage d\'un canapé par un professionnel","intro":"Le prix dépend avant tout de la taille du canapé, mais aussi de la matière, de l\'état et de la méthode de nettoyage. Chez Keepnew, la grille est simple et le déplacement est compris.","items":[{"label":"Canapé 1 à 3 places","price":"110 €"},{"label":"Canapé 4 à 5 places","price":"150 €"},{"label":"Canapé 6 à 8 places","price":"180 €"},{"label":"Canapé 8 places et +","price":"220 €"}],"note":"Prix déplacement compris. Si votre adresse est éloignée de notre zone d\'intervention, écrivez-nous avant de réserver. Prévoyez ensuite un temps de séchage de 12 à 24 heures.","visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"cream","h2":"Prenez RDV et payez après le nettoyage","body":"<p>Pas d\'acompte : le paiement intervient à la fin, quand vous avez constaté le résultat (carte, virement, QR code, ou facture si vous êtes une entreprise). Un canapé, un matelas et une voiture le même jour ? Dites-le-nous par téléphone au 0455 13 84 19.</p><p>Pour aller plus loin : <a href=\\"/blog/nettoyage-canape-fauteuil-tissu\\">tout savoir sur le nettoyage d\'un canapé en tissu</a> et <a href=\\"/blog/entreprise-nettoyage-canape-domicile-liege\\">comment choisir une entreprise de nettoyage de canapé</a>.</p>","cta_label":"Prendre RDV en ligne","cta_style":"primary","cta_align":"left","visible":["desktop","tablet","mobile"]},{"type":"accordion","bg":"white","eyebrow":"FAQ","h2":"Vos questions sur l\'entretien du canapé","items":[{"q":"Quelle est la fréquence idéale pour nettoyer son canapé ?","a":"Aspirez chaque semaine, traitez les taches tout de suite, et faites réaliser un nettoyage en profondeur au moins une fois par an, plus souvent avec enfants ou animaux."},{"q":"Peut-on utiliser du vinaigre ou du bicarbonate sur tous les canapés ?","a":"Non. Ces astuces conviennent à certains tissus seulement. Vérifiez l\'étiquette d\'entretien et testez toujours sur une zone cachée avant de traiter la tache."},{"q":"Comment enlever une tache sur un canapé en cuir ?","a":"Tamponnez avec un chiffon doux et un produit adapté au cuir, essuyez, puis hydratez. Sur une tache grasse, le talc aide à absorber avant de brosser délicatement."},{"q":"Un nettoyage professionnel abîme-t-il le canapé ?","a":"Au contraire : un professionnel adapte produits et méthode à la matière, ce qui limite les risques d\'auréoles, de décoloration ou de plis."},{"q":"Quand puis-je me rasseoir sur mon canapé après le passage du professionnel ?","a":"Le plus prudent est d\'attendre 12 à 24 heures, le temps que le tissu sèche complètement ; cela dépend de la matière et de l\'humidité de la pièce."},{"q":"Combien coûte un nettoyage de canapé professionnel ?","a":"Entre 110 € (1 à 3 places) et 220 € (8 places et plus), selon la taille, déplacement inclus."}],"visible":["desktop","tablet","mobile"]},{"type":"reviews","bg":"cream","eyebrow":"ILS NOUS FONT CONFIANCE","h2":"Ce que disent nos clients","visible":["desktop","tablet","mobile"]},{"type":"cta-final","bg":"blue","eyebrow":"RÉSERVATION EN LIGNE","title":"Redonnez de l\'éclat à <span class=\\"hl-inverse\\">votre canapé</span>","cta_title":"Prenez RDV en ligne","phone":"+32 (0)4 55 13 84 19","visible":["desktop","tablet","mobile"]}]', 'draft', NULL, (SELECT id FROM kn_categories WHERE slug = 'conseils-entretien' AND lang = 'fr' LIMIT 1), NULL, 'Comment bien nettoyer son canapé (tissu, cuir, velours) | Keepnew', 'Nettoyer son canapé tissu, cuir ou velours : conseils par matière, limites du nettoyage maison et quand faire appel à un professionnel (dès 110 €).', NULL
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM kn_posts WHERE slug = 'comment-bien-nettoyer-son-canape-et-quand-faire-appel-a-un-pro' AND lang = 'fr');
